// P2 Roofs: the main roofs of plots 0-3, the store and the coop (roof tool, one call each, since one roof.json holds one
// roof), and the hand-built porch shed roofs at z 6..8 (one stair course rising to the wall, tucked under the eave).
// Runs after the shell, so every roof is built into air and its chimneys pass through on `keep` boxes.
import { roof } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/roofs.mjs";
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { CHIMNEYS } from "../vocab/base.mjs";

// A chimney as a keep box: its stack plus the cap and fire above it (y 1 up to the fire course).
const stack = (c, top) => ({ from: [c[0], 1, c[2]], to: [c[3], top, c[5]] });

// Where a cap ring stands on the roof: the ring's stairs at the stack's flanks (x0-1 and x1+1) sit on the roof's slabs at
// the band course, so that course runs one block out under each ring stair as a full block (a stair on a bottom slab
// hangs half a block over air). Plots 1 and 2 only: their chimneys sit in the ridge or the west gable.
function ringFooting(g, c, y) {
  for (const x of [c[0] - 1, c[3] + 1]) for (let z = c[2]; z <= c[5]; z++) g.set(x, y, z, "deepslate_bricks");
}

// Porch shed roof on z 6..8 from x0 to x1 at course y (houses 6, store 7): slab over the step line at z 6, a stair
// course at z 7 rising to the wall, and a full block at z 8, which the main eave's row (y + 1) sits on.
function porchRoof(g, x0, x1, y, mat, block = mat) {
  for (let x = x0; x <= x1; x++) {
    g.set(x, y, 6, ...B.slab(mat, "bottom"));
    g.set(x, y, 7, ...B.stairs(mat, "south", "bottom"));
    g.set(x, y, 8, block);
  }
}

// Plot 0: shotgun, gable to the lane (ridge along z), polished andesite tin, birch verge. Chimney x 9..10.
// Plot 1: saddlebag duplex, side gable (ridge along x), mangrove tin, dark oak verge. Chimney in the ridge x 17..18.
// Plot 2: hall-and-parlour, side gable, spruce shingle. Chimney x 25..26 at the west gable.
// Plot 3: shotgun mirrored, green copper tin, dark oak verge. Chimney x 37..38.
const HOUSES = [
  { i: 0, box: [3, 9, 8, 17], ridgeAxis: "z", overhang: 1, material: { mix: [["polished_andesite", 3], ["birch", 1]], eave: "birch", ridge: "polished_andesite", verge: "birch" }, verge: "birch",
    gable: "birch_planks", chimney: CHIMNEYS.p0, top: 12,
    porch: { x0: 3, x1: 8, mat: "polished_andesite" } },
  { i: 1, box: [13, 9, 22, 16], ridgeAxis: "x", overhang: { north: 1, south: 1, east: 0, west: 0 }, material: { mix: [["mangrove", 3], ["dark_oak", 1]], eave: "dark_oak", ridge: "dark_oak", verge: "dark_oak" },
    verge: "dark_oak", gable: "spruce_planks", chimney: CHIMNEYS.p1, top: 14, footing: 11,
    porch: { x0: 13, x1: 22, mat: "mangrove", block: "mangrove_planks" } },
  { i: 2, box: [26, 9, 34, 16], ridgeAxis: "x", overhang: { north: 1, south: 1, east: 0, west: 0 }, material: { mix: [["spruce", 3], ["oak", 1]], eave: "oak", ridge: "oak", verge: "birch" },
    verge: "birch", gable: "oak_planks", chimney: CHIMNEYS.p2, top: 14, footing: 11,
    porch: { x0: 26, x1: 34, mat: "spruce", block: "spruce_planks" } },
  { i: 3, box: [39, 9, 44, 17], ridgeAxis: "z", overhang: 1, material: { mix: [["weathered_cut_copper", 3], ["dark_oak", 1]], eave: "dark_oak", ridge: "weathered_cut_copper", verge: "dark_oak" }, verge: "dark_oak",
    gable: "jungle_planks", chimney: CHIMNEYS.p3, top: 12,
    porch: { x0: 39, x1: 44, mat: "weathered_cut_copper" } },
];

export function build(g) {
  const out = [];
  for (const h of HOUSES) {
    const r = roof(g, h.box, "gable", {
      y: 7, pitch: 45, eave: "plain", ridge: "slab", ridgeAxis: h.ridgeAxis, front: "n",
      overhang: h.overhang, material: h.material, verge: h.verge, gable: h.gable, texture: h.texture,
      keep: [stack(h.chimney, h.top)],
    });
    out.push(`plot ${h.i} roof: ${r.cells ?? "?"} cells, refused ${r.refused ?? 0}`);
    if (h.footing) ringFooting(g, h.chimney, h.footing);
    porchRoof(g, h.porch.x0, h.porch.x1, 6, h.porch.mat, h.porch.block);
  }

  // Company store: low gable hidden behind the false front (its north gable is the front wall, so no overhang there).
  const store = roof(g, [85, 9, 94, 17], "gable", {
    y: 8, pitch: 0.5, eave: "plain", ridge: "slab", ridgeAxis: "z", front: "n",
    overhang: { north: 0, south: 1, east: 0, west: 0 }, material: { mix: [["polished_andesite", 3], ["dark_oak", 1]], eave: "dark_oak", ridge: "polished_andesite", verge: "dark_oak" }, verge: "dark_oak",
    keep: [{ from: [85, 3, 9], to: [94, 12, 9] }],
  });
  out.push(`store roof: ${store.cells ?? "?"} cells, refused ${store.refused ?? 0}`);
  // store porch: shed roof at y 7 under the false front, same course as the houses' porches
  porchRoof(g, 85, 94, 7, "polished_andesite");

  // Coop: small front gable (ridge along z), spruce tin, spruce verge; the gable ends are on the north and south.
  const coop = roof(g, [63, 12, 68, 16], "gable", {
    y: 5, pitch: 45, eave: "plain", ridge: "slab", ridgeAxis: "z", front: "n", overhang: 1,
    material: "spruce", texture: false, contrast: false, verge: "spruce",
  });
  out.push(`coop roof: ${coop.cells ?? "?"} cells, refused ${coop.refused ?? 0}`);
  return out;
}
// Room: P0 front room (interior designer's part). Inner air x 4..7, y 3..6, z 10..12; front door x 5..6 at z 9 and the
// open partition door x 5 at z 13 are the ways in. Furnished as a shotgun front room: a birch table with two chairs on
// the west side, a barrel dresser with a potted poppy, and a candle on the table for lamplight. The smoker at the east
// chimney (7,3,12) belongs to the hearths part and is left alone. Paths are kept clear: x 5..6 from the front door down to the partition door, and x 7 at z 11.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

// Y 3 (floor level): table post, chairs, barrel dresser.
//   F table post (birch_fence), C chair facing north (back to the front wall), D chair facing south,
//   B barrel facing up.
// Y 4: T table top slab (birch_slab, top half, sits on the post), P potted poppy on the barrel.
// Y 5: K candle lit on the table top.
const LEGEND = {
  F: "birch_fence",
  C: ["birch_stairs", { facing: "north" }],
  D: ["birch_stairs", { facing: "south" }],
  B: ["barrel", { facing: "up" }],
  T: ["birch_slab", { type: "top" }],
  P: "potted_poppy",
  K: ["candle", { candles: "1", lit: "true" }],
};

export function build(g) {
  layers(g, [4, 3, 10], LEGEND, [
    [
      "C  B", // z 10: chair at the front wall, barrel on the east wall
      "F  B", // z 11: table post, barrel
      "D   ", // z 12: chair at the partition
    ],
    [
      "   P", // z 10: potted poppy on the barrel
      "T   ", // z 11: table top
      "    ", // z 12
    ],
    [
      "    ",
      "K   ", // z 11: candle on the table
      "    ",
    ],
  ]);
}
// Room: P0 back room (interior designer's part): a shotgun bedroom. Inner air x4..7, y3..6, z14..16.
// Layout (floor y3, rows run along +z, columns along +x from x4):
//   bed (head west at x4, foot at x5, z15) against the west wall: the focal piece, in line with the partition door.
//   dresser: two chests against the east wall (x7, z14 and z16), a white carpet rug between them at z15.
//   bedside: a fence post with a standing lantern at x4 z16 (the one lamp), a lit candle and a potted poppy on the dresser.
// The walk: partition door (5,13) -> (5,14) -> (6,14) -> column x6 -> back door (6,17). Column x6 stays clear, and
// nothing sits in the doorway's first cell (5,14). Bed cells x4..5 z15 keep y4..5 clear above.
import { layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // The bed: foot at x5 z15, head one step west at x4 (the pillow end against the west wall).
  bed(g, [5, 3, 15], "west", "red");

  // Floor layer y3: rows z14, z15, z16; columns x4..x7. '.' is left as it is.
  // C = chest facing west (dresser), W = white carpet rug, F = fence post (bedside stand).
  // Layer y4: K = lit candle on the dresser, L = standing lantern on the fence post, P = potted poppy on a chest.
  layers(g, [4, 3, 14], {
    "C": ["chest", { facing: "west", type: "single" }],
    "W": "white_carpet",
    "F": "oak_fence",
    "K": ["candle", { candles: "3", lit: "true" }],
    "L": ["lantern", { hanging: "false" }],
    "P": "potted_poppy",
  }, [
    // y3 floor layer
    ["...C",
     "...W",
     "F..C"],
    // y4 layer (the lamp and the dresser top)
    ["...K",
     "....",
     "L..P"],
  ]);
}
// Room: P1 west flat (interior designer's part). Inner air x14..16, y3..6, z10..15; door x15 z9.
// Layout: the x15 column stays clear from the door to the back (the spine), so every cell on the x14 and x16 columns
// touches it. West: a pot barrel, a chair, the table (focal, by the stove), a chair, the bed (foot z14, head z15).
// East: the smoker by the party-wall chimney at z12, a chest, barrels with lanterns and a candle.
import { layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { stove } from "../vocab.mjs";

const LEGEND = {
  "B": ["barrel", { facing: "up" }],
  "c": ["spruce_stairs", { facing: "north" }],
  "d": ["spruce_stairs", { facing: "south" }],
  "T": "spruce_fence",
  "U": ["spruce_slab", { type: "top" }],
  "H": ["chest", { facing: "west" }],
  "P": "potted_poppy",
  "L": ["lantern", { hanging: "false" }],
  "N": ["candle", { candles: "2", lit: "true" }],
};

// rows run along +x (x14..16), successive rows along +z (z10..15)
const FLOOR = [
  "B B", // z10: pot barrel west, lamp barrel east
  "c  ", // z11: chair facing the table
  "T  ", // z12: table post; stove placed by stove() at x16
  "d H", // z13: chair facing the table; chest east
  "  B", // z14: bed foot (bed()) west; barrel east
  "  B", // z15: bed head (bed()) west; barrel east
];
const ABOVE = [
  "P L", // z10: pot on the barrel, lantern on the lamp barrel
  "   ",
  "U  ", // z12: table top slab
  "   ",
  "  L", // z14: lantern on barrel
  "  N", // z15: candles on barrel
];
const TABLE_TOP = [
  "   ",
  "   ",
  "L  ", // z12: lantern standing on the table top
  "   ",
  "   ",
  "   ",
];

export function build(g) {
  layers(g, [14, 3, 10], LEGEND, [FLOOR, ABOVE, TABLE_TOP]);
  bed(g, [14, 3, 14], "south", "red");
  stove(g, 16, 3, 12, "west");
}
// Room: P1 east flat (interior designer's part): the mirror of the west flat, one family's room on the chimney side.
// Focal piece: the lit smoker on the chimney wall (x19 z12), with the table and its chair in front of it. The bed sits
// at the back wall (x21 z14..15, head to the south wall); the barrels stand by the door. The x20 column stays clear as
// the lane from the door (x20 z9) to the bed. Light: a candle on the barrel, the lit smoker, a lantern on the table post.
import { layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

// Floor cells x19..21, z10..15 (origin 19,3,10). Layers: y3 (floor) and y4 (candle and table lantern).
const LEGEND = {
  B: ["barrel", { facing: "up" }],
  T: ["spruce_fence"],
  l: ["lantern", { hanging: "false" }],
  C: ["spruce_stairs", { facing: "south", half: "bottom", shape: "straight" }],
  t: ["candle", { candles: "2", lit: "true" }],
};

const ROWS = [
  [
    "B.B", // z10: barrels at x19 (dresser) and x21, the lane x20 clear
    "...", // z11
    "...", // z12: the smoker at x19 is the Hearths part's stove, already built
    "...", // z13
    "T..", // z14: table post
    "C..", // z15: chair, back to the south wall
  ],
  [
    "t..", // z10: candle on the barrel top
    "...",
    "...",
    "...",
    "l..", // z14: lantern standing on the table post (the table's lamp)
    "...",
  ],
];

export function build(g) {
  layers(g, [19, 3, 10], LEGEND, ROWS);
  bed(g, [21, 3, 14], "south", "red");
}
// Room: Coop nest room (interior designer's part). Inner air x64..67, y2..4, z13..15 (rooms.json box [64,2,13,67,4,15]).
// The nest row (hay_block and barrels facing up, along z15 at y2) is the coop shell's and already stands in the room, so
// it is the focal piece here: this part only adds the light. One standing lantern on the barrel at x65, z15 (level 10+
// over the whole room, min 10 at the feet). The floor is the coop shell's spruce at y1, so no straw is laid on y2: a full
// block there would take the walk height from y2 to y3.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // y3 layer, origin x64 z13: rows run along +x, successive rows along +z. Lantern at x65, z15, standing on the barrel.
  layers(g, [64, 3, 13], {
    l: ["lantern", { hanging: "false" }],
  }, [
    ["    ", "    ", " l  "],
  ]);
}

