8:const AIR = /(^|:)(cave_|void_)?air$/;
9:
10:/** One write, only into air: an earlier part's cell is never overwritten. */
11:function put(g, x, y, z, block, state) {
12:  if (!g.inBounds(x, y, z) || !AIR.test(g.blockAt(x, y, z))) return 0;
13:  g.set(x, y, z, block, state);
14:  return 1;
15:}
16:
17:/** A path cell on the ground row: the ground is the only block here that is not air, so it is written over directly. */
18:function ground(g, x, y, z, block) {
19:  g.set(x, y, z, block);
20:}
21:
22:/** A fence run on y1 through the given [x, z] cells: each post connects to its neighbours in the run. */
23:function fenceCells(g, cells, block) {
24:  const has = new Set(cells.map(([x, z]) => `${x},${z}`));
25:  let n = 0;
26:  for (const [x, z] of cells) {
27:    const dirs = {
28:      north: has.has(`${x},${z - 1}`), south: has.has(`${x},${z + 1}`),
29:      east: has.has(`${x + 1},${z}`), west: has.has(`${x - 1},${z}`),
30:    };
31:    const state = Object.fromEntries([...Object.entries(dirs).map(([d, on]) => [d, String(on)]), ["waterlogged", "false"]]);
32:    n += put(g, x, 1, z, block, state);
33:  }
34:  return n;
35:}
36:
37:/** The perimeter of the box x0..x1 by z0..z1 at ground row, leaving the cells in `gaps` open. */
38:function ring(x0, z0, x1, z1, gaps = []) {
39:  const skip = new Set(gaps.map(([x, z]) => `${x},${z}`));
40:  const cells = [];
41:  for (let x = x0; x <= x1; x++) { cells.push([x, z0], [x, z1]); }
42:  for (let z = z0 + 1; z < z1; z++) { cells.push([x0, z], [x1, z]); }
43:  return cells.filter(([x, z]) => !skip.has(`${x},${z}`));
44:}
